import json

def main(user_query: str) -> dict:
    text = (user_query or "").strip()
    if len(text) > 600:
        text = text[:600]
    # 固定锚点词保证命中 PowerContext 的词法召回门槛；
    # 每条记忆也带有同样的锚点，详见 docs/technical-note.md。
    memory_query = "酒馆 玩家 格罗姆 莉拉 老K " + text
    return {
        "memory_query": memory_query,
        "query_json": json.dumps(memory_query, ensure_ascii=False),
    }

import json


def _loads(text):
    try:
        return json.loads(text or "")
    except Exception:
        return None


def _prepare_items(body):
    data = _loads(body)
    if not isinstance(data, dict):
        return "unavailable", []
    # PowerContext 1.5 may wrap the payload in {"root": {...}}.
    root = data.get("root")
    if isinstance(root, dict):
        data = root
    status = str(data.get("status") or "unknown")
    content = data.get("content")
    if not content:
        return status, []
    marker = "BEGIN_POWERCONTEXT_PREPARED_CONTEXT_V1"
    end_marker = "END_POWERCONTEXT_PREPARED_CONTEXT_V1"
    start = content.find(marker)
    end = content.find(end_marker)
    if start == -1 or end == -1 or end <= start:
        return status, [content.strip()]
    chunk = content[start + len(marker):end].strip()
    inner = _loads(chunk)
    items = []
    if isinstance(inner, dict):
        for item in inner.get("items") or []:
            if isinstance(item, dict):
                value = str(item.get("content") or "").strip()
                if value:
                    items.append(value)
    if not items and chunk:
        items.append(chunk)
    return status, items


def _list_items(body):
    data = _loads(body)
    if not isinstance(data, dict):
        return []
    items = []
    for item in data.get("items") or []:
        if isinstance(item, dict):
            value = str(item.get("text") or "").strip()
            if value:
                items.append(value)
    return items


def _overlap(text, query):
    score = 0
    for index in range(len(query) - 1):
        pair = query[index:index + 2]
        if pair.strip() and pair in text:
            score += 1
    return score


def main(prepare_body: str, list_body: str, user_query: str) -> dict:
    status, relevant = _prepare_items(prepare_body)
    recent = _list_items(list_body)
    merged = []
    seen = set()
    for item in relevant + recent:
        key = item[:120]
        if key in seen:
            continue
        seen.add(key)
        merged.append(item)
    merged.sort(key=lambda value: -_overlap(value, user_query or ""))
    merged = merged[:8]
    if merged:
        memory_text = "\n".join("- " + item for item in merged)
    else:
        memory_text = "（酒馆旧账为空：这是玩家第一次留下记录，或检索服务暂不可用。）"
    return {
        "memory_text": memory_text,
        "memory_count": str(len(merged)),
        "prepare_status": status,
        "recent_count": str(len(recent)),
    }

