import json
import re


def _extract_json(text):
    start = text.find("{")
    end = text.rfind("}")
    if start == -1 or end <= start:
        return None
    chunk = text[start:end + 1]
    for candidate in (chunk, chunk.replace("\n", " ")):
        try:
            return json.loads(candidate)
        except Exception:
            continue
    return None


def main(llm_text: str) -> dict:
    text = (llm_text or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```[a-zA-Z]*\s*", "", text)
        if text.rstrip().endswith("```"):
            text = text.rstrip()[:-3].rstrip()

    data = _extract_json(text)

    if not isinstance(data, dict):
        safe = text.replace("**", "").strip()
        return {
            "dialogue": safe or "（酒馆里安静了几秒，没人接话。）",
            "footer": "",
            "memory_text": "",
            "memory_json": '""',
            "should_remember": "no",
            "speakers": "",
            "reply_ok": "no",
        }

    rendered = []
    speakers = []
    lines = data.get("lines")
    if isinstance(lines, list):
        for item in lines[:3]:
            if not isinstance(item, dict):
                continue
            speaker = str(item.get("speaker") or "旁白").strip()[:20]
            words = str(item.get("text") or "").strip()
            if not words:
                continue
            if speaker not in speakers:
                speakers.append(speaker)
            rendered.append("**" + speaker + "**：" + words)
    if not rendered:
        single = str(data.get("reply") or "").strip()
        if single:
            rendered.append(single)

    dialogue = "\n\n".join(rendered)
    if not dialogue:
        dialogue = "（酒馆里安静了几秒，没人接话。）"

    status = str(data.get("status") or "").strip()[:100]
    footer = ("\n\n> " + status) if status else ""

    memory = str(data.get("memory") or "").strip()
    memory = re.sub(r"\s+", " ", memory)[:300]
    memorable = str(data.get("memorable") or "no").strip().lower()
    should = "yes" if memorable in ("yes", "true", "1") and memory else "no"

    speaker_text = "、".join(speakers) if speakers else "在场的 NPC"
    memory_text = ""
    if memory:
        memory_text = (
            "酒馆记忆｜玩家：酒馆来客｜涉及：" + speaker_text
            + "｜在场：格罗姆、莉拉、老K｜详情：" + memory
        )

    return {
        "dialogue": dialogue,
        "footer": footer,
        "memory_text": memory_text,
        "memory_json": json.dumps(memory_text, ensure_ascii=False),
        "should_remember": should,
        "speakers": speaker_text,
        "reply_ok": "yes",
    }
